package com.ruanzhu.doorhandle.module.detection.service;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.ruanzhu.doorhandle.common.BusinessException;
import com.ruanzhu.doorhandle.contracts.security.BusinessUserDirectory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.scheduling.support.CronExpression;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.*;
import java.util.*;

/** Durable, permission-checked quality snapshots. Jobs never invoke a model or send notifications. */
@Service
@ConditionalOnProperty(prefix="app.quality-automation",name="enabled",havingValue="true")
public class QualityDigestService {
    private static final ZoneId DISPLAY_ZONE=ZoneId.of("Asia/Shanghai");
    private static final org.slf4j.Logger log=org.slf4j.LoggerFactory.getLogger(QualityDigestService.class);
    private final JdbcTemplate jdbc;private final BusinessUserDirectory users;private final ObjectMapper json;
    private final TransactionTemplate transactions;private final ReportDocumentRenderer renderer;private final ZoneId taskZone;
    public QualityDigestService(JdbcTemplate jdbc,BusinessUserDirectory users,ObjectMapper json,PlatformTransactionManager manager,ReportDocumentRenderer renderer,@Value("${app.quality-automation.task-time-zone:UTC}")String taskZone){this.jdbc=jdbc;this.users=users;this.json=json.copy().enable(SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS);this.transactions=new TransactionTemplate(manager);this.renderer=renderer;this.taskZone=ZoneId.of(taskZone);}
    private List<Map<String,Object>> rows(String sql,Object... arguments){return jdbc.query(sql,com.ruanzhu.doorhandle.common.LocalDateTimeRow::read,arguments);}
    private Map<String,Object> row(String sql,Object... arguments){var rows=rows(sql,arguments);if(rows.size()!=1)throw new IllegalStateException("数据记录未完整读取");return rows.get(0);}
    private static LocalDateTime now(){return LocalDateTime.now(ZoneOffset.UTC);}
    private BusinessUserDirectory.Identity actor(){var actor=users.authenticated();actor=users.current(actor.userId(),actor.username());if(!actor.supervisor())throw fail(403,"仅主管可管理质检日报");return actor;}
    private Map<String,Object> owned(String id,long user,boolean lock){var rows=rows("SELECT * FROM quality_digest_schedule WHERE schedule_id=? AND owner_user_id=?"+(lock?" FOR UPDATE":""),id,user);if(rows.isEmpty())throw fail(404,"计划不存在或无访问权限");return rows.get(0);}
    public List<Map<String,Object>> schedules(){return rows("SELECT * FROM quality_digest_schedule WHERE owner_user_id=? ORDER BY id DESC LIMIT 100",actor().userId());}
    public record Save(String name,String cronExpression,boolean enabled,int expectedVersion,String requestId){}
    public Map<String,Object> save(String id,Save request){var caller=actor();if(request.name()==null||request.name().isBlank()||request.name().length()>120||request.cronExpression()==null||request.cronExpression().length()>100)throw fail(400,"计划名称或时间表达式不正确");requestId(request.requestId());var cron=cron(request.cronExpression());String digest=sha(Objects.toString(id,"")+"\n"+write(request));return transactions.execute(status->{var fresh=users.lockCurrent(caller.userId(),caller.username());if(!fresh.supervisor())throw fail(403,"当前账号已无主管权限");control();var repeated=rows("SELECT request_sha256,schedule_id FROM quality_digest_command WHERE actor_user_id=? AND request_id=?",fresh.userId(),request.requestId());if(!repeated.isEmpty()){if(!digest.equals(repeated.get(0).get("request_sha256")))throw fail(409,"请求编号已用于其他计划操作");return owned(repeated.get(0).get("schedule_id").toString(),fresh.userId(),false);}String scheduleId=id;
            if(scheduleId==null){if(request.expectedVersion()!=0)throw fail(409,"新计划的版本应为零");if(jdbc.queryForObject("SELECT COUNT(*) FROM quality_digest_schedule WHERE owner_user_id=?",Long.class,fresh.userId())>=50)throw fail(409,"最多保留 50 个计划");scheduleId="qs-"+UUID.randomUUID();jdbc.update("INSERT INTO quality_digest_schedule(schedule_id,owner_user_id,owner_username,name,cron_expression,enabled,version,next_fire_at,created_at,updated_at) VALUES(?,?,?,?,?,?,1,?,?,?)",scheduleId,fresh.userId(),fresh.username(),request.name().strip(),request.cronExpression().strip(),request.enabled(),request.enabled()?next(cron):null,now(),now());}
            else{var old=owned(scheduleId,fresh.userId(),true);if(((Number)old.get("version")).intValue()!=request.expectedVersion())throw fail(409,"计划已更新，请重新读取");jdbc.update("UPDATE quality_digest_schedule SET name=?,cron_expression=?,enabled=?,version=version+1,next_fire_at=?,updated_at=? WHERE schedule_id=?",request.name().strip(),request.cronExpression().strip(),request.enabled(),request.enabled()?next(cron):null,now(),scheduleId);}
            jdbc.update("INSERT INTO quality_digest_command(actor_user_id,request_id,request_sha256,schedule_id,created_at) VALUES(?,?,?,?,?)",fresh.userId(),request.requestId(),digest,scheduleId,now());audit(scheduleId,fresh.userId(),"SAVE",request.expectedVersion()+1,Map.of("cron",request.cronExpression(),"enabled",request.enabled()));return owned(scheduleId,fresh.userId(),false);
        });}
    public record Generate(LocalDate reportDate,int expectedVersion,String requestId){}
    public Map<String,Object> generate(String id,Generate request){var caller=actor();requestId(request.requestId());if(request.reportDate()==null||request.reportDate().isAfter(LocalDate.now(DISPLAY_ZONE))||request.reportDate().isBefore(LocalDate.now(DISPLAY_ZONE).minusYears(10)))throw fail(400,"日报日期不正确");return transactions.execute(status->{var fresh=users.lockCurrent(caller.userId(),caller.username());if(!fresh.supervisor())throw fail(403,"当前账号已无主管权限");control();var schedule=owned(id,fresh.userId(),true);String key="manual:"+request.requestId();var repeated=rows("SELECT run_id,report_date FROM quality_digest_run WHERE schedule_id=? AND request_key=?",id,key);if(!repeated.isEmpty()){if(!request.reportDate().toString().equals(repeated.get(0).get("report_date").toString()))throw fail(409,"请求编号已用于其他日期");return Map.of("runId",repeated.get(0).get("run_id"),"status","QUEUED_OR_EXISTING");}if(((Number)schedule.get("version")).intValue()!=request.expectedVersion())throw fail(409,"计划已更新，请重新读取");quota(fresh.userId());String run=enqueue(id,fresh.userId(),key,now(),request.reportDate());audit(id,fresh.userId(),"GENERATE",request.expectedVersion(),Map.of("runId",run,"reportDate",request.reportDate().toString()));return Map.of("runId",run,"status","PENDING");});}
    private String enqueue(String id,long owner,String key,LocalDateTime slot,LocalDate date){String run="qd-"+UUID.randomUUID();jdbc.update("INSERT INTO quality_digest_run(run_id,schedule_id,owner_user_id,request_key,scheduled_for,report_date,status,created_at) VALUES(?,?,?,?,?,?,'PENDING',?)",run,id,owner,key,slot,date,now());return run;}
    public List<Map<String,Object>> runs(String id){var caller=actor();owned(id,caller.userId(),false);return rows("SELECT run_id,report_date,status,snapshot_sha256,error_code,created_at,finished_at FROM quality_digest_run WHERE schedule_id=? AND owner_user_id=? ORDER BY id DESC LIMIT 100",id,caller.userId());}
    @Scheduled(fixedDelayString="${app.quality-automation.poll-ms:30000}")
    public void pump(){try{for(int i=0;i<3;i++)allocate();for(int i=0;i<2;i++)work();}catch(RuntimeException error){log.warn("质检日报调度暂不可用；保留持久状态等待下一调度周期");}}
    private void allocate(){transactions.executeWithoutResult(status->{control();var due=rows("SELECT * FROM quality_digest_schedule WHERE enabled=TRUE AND next_fire_at<=? ORDER BY next_fire_at,id LIMIT 1 FOR UPDATE SKIP LOCKED",now());if(due.isEmpty())return;var row=due.get(0);String id=row.get("schedule_id").toString();long owner=((Number)row.get("owner_user_id")).longValue();try{if(!users.current(owner,row.get("owner_username").toString()).supervisor())throw new SecurityException();}catch(SecurityException error){jdbc.update("UPDATE quality_digest_schedule SET enabled=FALSE,version=version+1,updated_at=? WHERE schedule_id=?",now(),id);audit(id,owner,"PERMISSION_BLOCKED",((Number)row.get("version")).intValue(),Map.of());return;}try{quota(owner);}catch(BusinessException limited){jdbc.update("UPDATE quality_digest_schedule SET enabled=FALSE,version=version+1,updated_at=? WHERE schedule_id=?",now(),id);audit(id,owner,"RUN_QUOTA_BLOCKED",((Number)row.get("version")).intValue(),Map.of());return;}LocalDateTime slot=time(row.get("next_fire_at"));var localSlot=slot.atOffset(ZoneOffset.UTC).atZoneSameInstant(DISPLAY_ZONE);enqueue(id,owner,"scheduled:"+slot,slot,localSlot.toLocalDate().minusDays(1));jdbc.update("UPDATE quality_digest_schedule SET next_fire_at=?,updated_at=? WHERE schedule_id=?",next(cron(row.get("cron_expression").toString())),now(),id);});}
    private void work(){var claim=transactions.execute(status->{var rows=rows("SELECT * FROM quality_digest_run WHERE status='PENDING' OR (status='RUNNING' AND lease_until<?) ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED",now());if(rows.isEmpty())return null;var row=rows.get(0);String token=UUID.randomUUID().toString();jdbc.update("UPDATE quality_digest_run SET status='RUNNING',claim_token=?,lease_until=? WHERE run_id=?",token,now().plusMinutes(5),row.get("run_id"));row.put("claim_token",token);return row;});if(claim==null)return;String run=claim.get("run_id").toString(),token=claim.get("claim_token").toString();
        try{var schedule=row("SELECT owner_username FROM quality_digest_schedule WHERE schedule_id=?",claim.get("schedule_id"));if(!users.current(((Number)claim.get("owner_user_id")).longValue(),schedule.get("owner_username").toString()).supervisor())throw new SecurityException();LocalDate date=LocalDate.parse(claim.get("report_date").toString());String snapshot=write(snapshot(date));transactions.executeWithoutResult(status->{var owner=users.lockCurrent(((Number)claim.get("owner_user_id")).longValue(),schedule.get("owner_username").toString());if(!owner.supervisor())throw new SecurityException();jdbc.update("UPDATE quality_digest_run SET status='COMPLETED',snapshot_json=?,snapshot_sha256=?,finished_at=?,lease_until=NULL WHERE run_id=? AND status='RUNNING' AND claim_token=? AND lease_until>=?",snapshot,sha(snapshot),now(),run,token,now());});
        }catch(RuntimeException error){String state=error instanceof SecurityException?"BLOCKED":"FAILED";transactions.executeWithoutResult(status->jdbc.update("UPDATE quality_digest_run SET status=?,error_code=?,finished_at=?,lease_until=NULL WHERE run_id=? AND status='RUNNING' AND claim_token=?",state,state.equals("BLOCKED")?"AUTHORITY_REVOKED":"SNAPSHOT_UNAVAILABLE",now(),run,token));}}
    private Map<String,Object> snapshot(LocalDate date){LocalDateTime from=date.atStartOfDay(DISPLAY_ZONE).withZoneSameInstant(taskZone).toLocalDateTime(),to=date.plusDays(1).atStartOfDay(DISPLAY_ZONE).withZoneSameInstant(taskZone).toLocalDateTime();var rows=rows("SELECT status,COUNT(*) AS taskCount,COALESCE(SUM(total_images),0) AS imageCount,COALESCE(SUM(successful_images),0) AS successfulImages,COALESCE(SUM(failed_images),0) AS failedImages,COALESCE(SUM(defect_count),0) AS modelDefectTargets,COALESCE(SUM(CASE WHEN review_status='PENDING' THEN 1 ELSE 0 END),0) AS pendingReviewCount,COALESCE(SUM(CASE WHEN review_status IS NULL THEN 1 ELSE 0 END),0) AS unrecordedReviewCount FROM detection_task WHERE created_at>=? AND created_at<? GROUP BY status ORDER BY status",from,to);return Map.of("reportDate",date.toString(),"timeZone",DISPLAY_ZONE.getId(),"taskStorageZone",taskZone.getId(),"basis","该日创建任务的当前状态快照；模型缺陷目标数不代表人工确认结果", "generatedAt",Instant.now().toString(),"statusGroups",rows);}
    public ReportDocumentRenderer.File download(String runId,String format){var caller=actor();return transactions.execute(status->{var fresh=users.lockCurrent(caller.userId(),caller.username());if(!fresh.supervisor())throw fail(403,"当前账号已无主管权限");var rows=rows("SELECT * FROM quality_digest_run WHERE run_id=? AND owner_user_id=? AND status='COMPLETED'",runId,fresh.userId());if(rows.isEmpty())throw fail(404,"日报尚未完成或无访问权限");var row=rows.get(0);String snapshot=canonical(row.get("snapshot_json").toString());if(!sha(snapshot).equals(row.get("snapshot_sha256")))throw fail(409,"日报快照摘要不一致");String text=markdown(snapshot,row.get("snapshot_sha256").toString());ReportDocumentRenderer.File file;if("md".equals(format))file=new ReportDocumentRenderer.File(text.getBytes(StandardCharsets.UTF_8),"text/markdown","md");else file=renderer.render(text,format);audit(row.get("schedule_id").toString(),fresh.userId(),"DOWNLOAD",0,Map.of("runId",runId,"format",format,"snapshotSha256",row.get("snapshot_sha256")));return file;});}
    private String markdown(String encoded,String hash){try{var root=json.readTree(encoded);var text=new StringBuilder("# 质检统计日报\n\n日期："+root.path("reportDate").asText()+"\n时区：Asia/Shanghai\n统计口径："+root.path("basis").asText()+"\n快照 SHA-256："+hash+"\n\n");for(var row:root.path("statusGroups")){text.append("## ").append(Map.of("COMPLETED","已完成","PARTIAL_FAILED","部分失败","FAILED","执行失败","RUNNING","检测中","UPLOADING","上传中","QUEUED","等待调度","DISPATCHING","派发中","CANCELLED","已取消").getOrDefault(row.path("status").asText(),row.path("status").asText())).append("\n");for(var item:Map.of("taskCount","任务数","imageCount","图片数","successfulImages","成功图片","failedImages","失败图片","modelDefectTargets","模型缺陷目标","pendingReviewCount","登记待复核","unrecordedReviewCount","未登记复核状态").entrySet())text.append(item.getValue()).append("：").append(row.path(item.getKey()).asLong()).append("\n");}if(root.path("statusGroups").isEmpty())text.append("该日暂无创建的检测任务\n");return text.append("\n本文件为统计快照，不替代人工复核、产品放行或报告审批。\n").toString();}catch(Exception error){throw fail(409,"日报快照无法读取");}}
    private void control(){jdbc.queryForObject("SELECT control_id FROM quality_digest_control WHERE control_id=1 FOR UPDATE",Integer.class);}
    private void quota(long owner){var start=LocalDate.now(DISPLAY_ZONE).atStartOfDay(DISPLAY_ZONE).withZoneSameInstant(ZoneOffset.UTC).toLocalDateTime();if(jdbc.queryForObject("SELECT COUNT(*) FROM quality_digest_run WHERE owner_user_id=?",Long.class,owner)>=5000||jdbc.queryForObject("SELECT COUNT(*) FROM quality_digest_run WHERE owner_user_id=? AND created_at>=?",Long.class,owner,start)>=500)throw fail(429,"日报数量已达保留或当日上限，请先整理计划");}
    private String canonical(String encoded){try{return write(json.readValue(encoded,Object.class));}catch(Exception error){throw fail(409,"日报快照无法读取");}}
    private static CronExpression cron(String value){try{String text=value.strip();if(!text.split("\\s+")[0].equals("0"))throw new IllegalArgumentException();var cron=CronExpression.parse(text);next(cron);return cron;}catch(RuntimeException error){throw fail(400,"请使用六段 Cron，秒位固定为 0；例如每天 08:00：0 0 8 * * *");}}
    private static LocalDateTime next(CronExpression cron){var next=cron.next(ZonedDateTime.now(DISPLAY_ZONE));if(next==null)throw fail(400,"时间表达式没有后续执行时间");return next.withZoneSameInstant(ZoneOffset.UTC).toLocalDateTime();}
    private static LocalDateTime time(Object value){return value instanceof java.sql.Timestamp timestamp?timestamp.toLocalDateTime():(LocalDateTime)value;}
    private void audit(String id,long user,String action,int version,Object detail){jdbc.update("INSERT INTO quality_digest_audit(schedule_id,actor_user_id,action_name,version,detail_json,created_at) VALUES(?,?,?,?,?,?)",id,user,action,version,write(detail),now());}
    private String write(Object value){try{return json.writeValueAsString(value);}catch(Exception error){throw new IllegalStateException("日报内容不能序列化");}}
    private static String sha(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception error){throw new IllegalStateException(error);}}
    private static void requestId(String value){if(value==null||!value.matches("[A-Za-z0-9_-]{8,64}"))throw fail(400,"请求编号不正确");}
    private static BusinessException fail(int status,String message){return new BusinessException(status,message);}
}
